  "I struggle with fast native speakers.": "나는 빠른 원어민과 어려움을 겪습니다.",
  "I suggest we leave early.": "일찍 떠나는 것이 좋습니다.",
  "I suppose we could walk.": "우리는 걸을 수 있을 것 같아요.",
  "I survived my first Finnish winter!": "나는 핀란드의 첫 겨울을 살아 남았습니다!",
