  "Sorry, is this an inconvenient time?": "죄송합니다. 지금 불편한 시간인가요?",
  "A warm coat is essential.": "따뜻한 코트는 필수입니다.",
  "I'm exhausted after the long flight.": "긴 비행으로 피곤해요.",
  "This street looks familiar.": "이 거리는 낯익은 ​​것 같아요.",
  "The sauna was fantastic.": "사우나는 환상적이었습니다.",
  "What a gorgeous view!": "정말 멋진 전망이에요!",
  "This app is really handy.": "이 앱은 정말 편리합니다.",
