  "Is my ticket still valid?": "내 티켓이 아직 유효한가요?",
  "Is the museum worth visiting?": "박물관은 방문할 가치가 있나요?",
  "The view from the tower is breathtaking.": "타워에서 바라보는 경치는 숨이 막힐 정도입니다.",
