  "Entrance exam pressure starts early in Korea.": "한국은 입시 압박이 일찍 시작된다.",
  "Korean high schools have evening self-study time.": "한국 고등학교에는 저녁 자율 학습 시간이 있습니다.",
  "Finnish students don't wear school uniforms.": "핀란드 학생들은 교복을 입지 않습니다.",
