  "We have a morning assembly on Mondays.": "월요일에는 아침조회가 있습니다.",
  "Homeroom period is ten minutes long.": "홈룸 시간은 10분입니다.",
  "Club activities are on Friday afternoons.": "클럽 활동은 금요일 오후에 있습니다.",
  "Sports day is a big event in Korean schools.": "운동회는 한국 학교에서 큰 행사이다.",
  "Our school festival is in October.": "우리 학교 축제는 10월에 있어요.",
  "The graduation ceremony is in February.": "졸업식은 2월이다.",
  "The entrance ceremony is in March.": "입학식은 3월이다.",
