  "There's a parents' evening next week.": "다음주에 학부모회의가 있습니다.",
  "Parents get messages through Wilma.": "학부모들은 Wilma를 통해 메시지를 받습니다.",
  "Good home-school communication builds trust.": "가정-학교 간의 원활한 의사소통은 신뢰를 구축합니다.",
