  "How do you handle parent complaints?": "학부모 불만사항은 어떻게 처리하나요?",
  "Teacher authority is a hot topic in Korea.": "교사의 권위는 한국에서 뜨거운 이슈이다.",
  "The teachers' union is very strong here.": "이곳의 교사 노조는 매우 강력합니다.",
  "Teacher salaries are average for Finland.": "교사 급여는 핀란드 평균 수준입니다.",
  "Working conditions are quite good.": "근무조건은 상당히 좋습니다.",
  "Teachers report high job satisfaction.": "교사들은 직업 만족도가 높다고 보고합니다.",
  "There's a shortage of special education teachers.": "특수교사가 부족해요.",
  "What's the career path for teachers?": "교사의 진로는 어떻게 되나요?",
  "Promotion usually means becoming a principal.": "승진은 대개 교장이 되는 것을 의미한다.",
  "Can teachers take a sabbatical?": "교사가 안식년을 가질 수 있나요?",
