  "As you can see, class sizes are large.": "보시다시피 수업 ​​규모가 큽니다.",
  "This slide shows our weekly timetable.": "이 슬라이드는 주간 시간표를 보여줍니다.",
  "Let me give you an example from my class.": "제 수업의 예를 하나 들어보겠습니다.",
  "Moving on, let's look at assessment.": "이어서 평가를 살펴보겠습니다.",
  "To illustrate, here's a student's portfolio.": "설명을 위해 여기에 학생의 포트폴리오가 있습니다.",
