  "That's a great question. Let me think.": "좋은 질문입니다. 생각해보자.",
  "I'm not sure, but I think it's around 20%.": "잘은 모르겠지만 20% 정도 되는 것 같아요.",
  "Let me get back to you on that.": "이에 대해서는 다시 연락드리겠습니다.",
