  "What's a typical day like for you?": "당신의 전형적인 하루는 어떤가요?",
  "What do you enjoy most about teaching?": "가르치면서 가장 즐거운 점은 무엇입니까?",
  "If you could, what would you change?": "가능하다면 무엇을 바꾸시겠습니까?",
  "That's really interesting. We do it differently.": "정말 흥미롭습니다. 우리는 다르게 행동합니다.",
