  "Let's keep in touch by email.": "이메일로 계속 연락합시다.",
  "Thank you so much for having us today.": "오늘 우리를 초대해 주셔서 정말 감사합니다.",
  "It's been very inspiring to visit your school.": "당신의 학교를 방문하는 것은 매우 고무적인 일이었습니다.",
  "I learned a lot today. Thank you.": "오늘 많은 것을 배웠습니다. 감사합니다.",
