  "Sorry, you're on mute.": "죄송합니다. 현재 음소거 중입니다.",
  "Let me share my screen.": "내 화면을 공유하겠습니다.",
  "Can you see my screen now?": "지금 내 화면을 볼 수 있나요?",
  "Sorry, the connection is unstable.": "죄송합니다. 연결이 불안정합니다.",
