  "School meals are free of charge.": "학교 급식은 무료입니다.",
  "Compulsory education now lasts until 18.": "이제 의무교육은 18세까지 지속됩니다.",
  "The school starting age is seven.": "학교 시작 연령은 7세입니다.",
