  "What are the entrance requirements?": "입학 요건은 무엇입니까?",
  "Many Finns take a gap year before university.": "많은 핀란드인들은 대학에 가기 전에 갭이어(Gap Year)를 가집니다.",
  "Career counseling starts in grade seven.": "진로 상담은 7학년부터 시작됩니다.",
  "The guidance counselor helps students choose.": "지도 카운슬러는 학생들이 선택할 수 있도록 도와줍니다.",
