  "I'm worn out, but it was a good day.": "피곤하긴 했지만 좋은 하루였습니다.",
  "I felt a bit overwhelmed on my first day.": "첫날에는 좀 벅찬 느낌이 들었습니다.",
  "I was so relieved when the meeting was cancelled.": "회의가 취소되었을 때 나는 너무 안도감을 느꼈다.",
  "I'm thrilled that our application was accepted!": "우리의 지원서가 승인되어 정말 기쁩니다!",
  "I get frustrated when I can't find the right words.": "나는 적절한 단어를 찾을 수 없을 때 좌절감을 느낀다.",
  "I feel self-conscious about my accent.": "나는 내 억양에 대해 자의식을 느낀다.",
  "I was intimidated at first, but everyone was so kind.": "처음엔 겁이 났는데 다들 너무 친절하셨어요.",
  "Your colleagues made me feel at ease.": "동료들이 나를 편안하게 해줬어요.",
  "Teaching can be exhausting but incredibly fulfilling.": "가르치는 일은 지칠 수도 있지만 믿을 수 없을 정도로 성취감을 줍니다.",
  "Seeing a shy student speak up is so rewarding.": "수줍음이 많은 학생이 말하는 모습을 보는 것은 정말 보람 있는 일입니다.",
  "I'm grateful for the chance to learn from you.": "당신에게서 배울 수 있는 기회를 주셔서 감사합니다.",
  "It was humbling to see how much I still have to learn.": "아직 배워야 할 것이 얼마나 많은지 보니 겸손해졌습니다.",
  "Your teaching style is really inspiring.": "당신의 교육 스타일은 정말 고무적입니다.",
  "I was really moved by the students' performance.": "학생들의 공연에 정말 감동받았습니다.",
