  "Sauna is the Finnish way to let off steam.": "사우나는 피로를 풀어주는 핀란드식 방법입니다.",
  "I like to unwind with a book after dinner.": "나는 저녁 식사 후에 책을 읽으며 긴장을 푸는 것을 좋아합니다.",
  "You've worked hard. Take it easy tonight.": "당신은 열심히 일했습니다. 오늘 밤은 편히 쉬세요.",
