  "Teachers often burn the midnight oil before exams.": "교사들은 시험 전에 밤늦게까지 시간을 보내는 경우가 많습니다.",
  "I can't decide now. Let me sleep on it.": "지금은 결정할 수 없습니다. 자도록 할게요.",
