  "I got tongue-tied when the principal asked me a question.": "교장 선생님이 나에게 질문을 했을 때 나는 말문이 막혔다.",
  "The word is on the tip of my tongue.": "그 말이 혀끝에 맴돈다.",
  "Don't be afraid to speak up in meetings.": "회의에서 말하는 것을 두려워하지 마십시오.",
