  "You have a point. Maybe we're overplanning.": "당신은 요점이 있습니다. 어쩌면 우리가 너무 계획을 세우고 있는 것일 수도 있습니다.",
  "Let's agree to disagree on that one.": "그 점에 대해서는 동의하지 않는다는 점에 동의합시다.",
  "Just to play devil's advocate, is less homework always better?": "악마의 옹호자 역할을 하려면 숙제가 적은 것이 항상 더 좋은가요?",
