  "The teachers here are so down-to-earth.": "여기 선생님들은 정말 현실적이에요.",
  "Finns can seem reserved at first, but they're very warm.": "핀란드 사람들은 처음에는 내성적인 것처럼 보이지만 매우 따뜻합니다.",
  "Their kindness feels genuine.": "그들의 친절은 진심으로 느껴집니다.",
  "Finns are very punctual, so don't be late.": "핀란드인들은 시간을 잘 지키므로 늦지 마세요.",
